  payload=json.dumps(d,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c');script=JS.replace('__DATA__',payload).replace('__META__',json.dumps(meta));page=page.replace('__SCRIPT__',script);(p/'depth-demo.html').write_text(page);print('Refined',p.name)
